// src/components/SignIn.js
import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { toast } from 'react-toastify';

const SignIn = ({ onAuth }) => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({ email: '', password: '' });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (formData.email && formData.password) {
      onAuth({ name: 'User', email: formData.email });
      toast.success('Welcome back!');
      navigate('/dashboard');
    } else {
      toast.error('Please fill in all fields');
    }
  };

  const handleClose = () => {
    navigate('/');
  };

  return (
    <div className="d-flex justify-content-center align-items-center min-vh-100" style={{ backgroundColor: '#fffaf2' }}>
      <div className="card p-4 shadow-lg" style={{ width: '100%', maxWidth: '400px', borderRadius: '1rem' }}>
        <button onClick={handleClose} className="btn-close position-absolute end-0 m-3" aria-label="Close"></button>

        <h2 className="text-center mb-4 text-primary">Welcome Back</h2>

        <form onSubmit={handleSubmit}>
          <div className="mb-3">
            <label className="form-label">Email</label>
            <input
              type="email"
              name="email"
              className="form-control"
              value={formData.email}
              onChange={handleChange}
              placeholder="you@example.com"
              required
            />
          </div>

          <div className="mb-3">
            <label className="form-label">Password</label>
            <input
              type="password"
              name="password"
              className="form-control"
              value={formData.password}
              onChange={handleChange}
              placeholder="••••••••"
              required
            />
          </div>

          <div className="mb-3 text-end">
            <Link to="/forgot-password" className="text-decoration-none text-warning" style={{ fontSize: '0.9rem' }}>
              Forgot password?
            </Link>
          </div>

          <button type="submit" className="btn btn-primary w-100">Sign In</button>

          <div className="text-center my-3 text-muted">or</div>

          <button className="btn btn-outline-secondary w-100 d-flex align-items-center justify-content-center">
            <img
              src="https://www.gstatic.com/firebasejs/ui/2.0.0/images/auth/google.svg"
              alt="Google"
              style={{ width: '20px', marginRight: '10px' }}
            />
            Sign in with Google
          </button>
        </form>

        <p className="text-center mt-3 text-muted">
          Don’t have an account? <Link to="/signup" className="text-decoration-none text-primary">Sign Up</Link>
        </p>
      </div>
    </div>
  );
};

export default SignIn;
